class Order:
    def __init__(self):
        self.state = 'created'

    def pay(self):
        if self.state == 'created':
            self.state = 'paid'
            return True
        return False

    def ship(self):
        if self.state == 'paid':
            self.state = 'shipped'
            return True
        return False

    def complete(self):
        if self.state == 'shipped':
            self.state = 'done'
            return True
        return False

    def cancel(self):
        if self.state in ('created', 'paid'):
            self.state = 'cancelled'
            return True
        return False
```

